using LUMAR_ERP_API_V2.Data;using LUMAR_ERP_API_V2.DTOs.Messages;using Microsoft.Data.SqlClient;namespace LUMAR_ERP_API_V2.Repositories;
public sealed class MessageRepository(ReadOnlySqlConnectionFactory connections):IMessageRepository{public Task<IReadOnlyList<CustomerMessageDto>> GetCustomerMessagesAsync(CancellationToken c)=>Q("SELECT CustomerMessageID,CustomerID,OrderID,EventType,TemplateKey,Channel,Title,Body,DeliveryStatus,CreatedAtUtc,SentAtUtc,ReadAtUtc,AttemptCount,DeliveredAtUtc FROM dbo.CustomerMessages ORDER BY CreatedAtUtc DESC,CustomerMessageID DESC",null,Message,c);public async Task<CustomerMessageDto?> GetCustomerMessageAsync(int i,CancellationToken c)=>(await Q("SELECT CustomerMessageID,CustomerID,OrderID,EventType,TemplateKey,Channel,Title,Body,DeliveryStatus,CreatedAtUtc,SentAtUtc,ReadAtUtc,AttemptCount,DeliveredAtUtc FROM dbo.CustomerMessages WHERE CustomerMessageID=@id",i,Message,c)).FirstOrDefault();public Task<IReadOnlyList<CustomerMessageDto>> GetCustomerMessagesAsync(int i,CancellationToken c)=>Q("SELECT CustomerMessageID,CustomerID,OrderID,EventType,TemplateKey,Channel,Title,Body,DeliveryStatus,CreatedAtUtc,SentAtUtc,ReadAtUtc,AttemptCount,DeliveredAtUtc FROM dbo.CustomerMessages WHERE CustomerID=@id ORDER BY CreatedAtUtc DESC,CustomerMessageID DESC",i,Message,c);public Task<IReadOnlyList<CustomerNotificationDto>> GetNotificationsAsync(CancellationToken c)=>Q("SELECT CustomerNotificationID,CustomerID,OrderID,EventType,Title,Body,Status,IsRead,CreatedAtUtc,ReadAtUtc,CustomerMessageID FROM dbo.CustomerNotifications ORDER BY CreatedAtUtc DESC,CustomerNotificationID DESC",null,Notification,c);public Task<IReadOnlyList<CustomerNotificationDto>> GetNotificationsAsync(int i,CancellationToken c)=>Q("SELECT CustomerNotificationID,CustomerID,OrderID,EventType,Title,Body,Status,IsRead,CreatedAtUtc,ReadAtUtc,CustomerMessageID FROM dbo.CustomerNotifications WHERE CustomerID=@id ORDER BY CreatedAtUtc DESC,CustomerNotificationID DESC",i,Notification,c);public Task<IReadOnlyList<MessageTemplateDto>> GetTemplatesAsync(CancellationToken c)=>Q("SELECT MessageTemplateID AS TemplateId,'MessageTemplates' AS SourceTable,TemplateKey,NULL AS TemplateName,Title,Channel,Body,IsActive,CreatedAtUtc,UpdatedAtUtc FROM dbo.MessageTemplates UNION ALL SELECT TemplateID,'Messages_Templates',NULL,TemplateName,NULL,NULL,MessageText,NULL,NULL,NULL FROM dbo.Messages_Templates",null,Template,c);public Task<IReadOnlyList<MessageTemplateDto>> GetTemplatesByIdAsync(int i,CancellationToken c)=>Q("SELECT MessageTemplateID AS TemplateId,'MessageTemplates' AS SourceTable,TemplateKey,NULL AS TemplateName,Title,Channel,Body,IsActive,CreatedAtUtc,UpdatedAtUtc FROM dbo.MessageTemplates WHERE MessageTemplateID=@id UNION ALL SELECT TemplateID,'Messages_Templates',NULL,TemplateName,NULL,NULL,MessageText,NULL,NULL,NULL FROM dbo.Messages_Templates WHERE TemplateID=@id",i,Template,c);public Task<IReadOnlyList<SentMessageDto>> GetSentAsync(CancellationToken c)=>Q("SELECT MessageID,TrackingCode,CustomerID,MessageText,SentDate FROM dbo.Sent_Messages ORDER BY SentDate DESC,MessageID DESC",null,r=>new SentMessageDto(r.GetInt32(0),r.NullableInt32("TrackingCode"),r.NullableInt32("CustomerID"),r.NullableString("MessageText"),r.NullableDateTime("SentDate")),c);public Task<IReadOnlyList<SentLogDto>> GetSentLogAsync(CancellationToken c)=>Q("SELECT ID,MessageID FROM dbo.Sent_Log ORDER BY ID DESC",null,r=>new SentLogDto(r.GetInt32(0),r.NullableInt32("MessageID")),c);private static CustomerMessageDto Message(SqlDataReader r)=>new(r.GetInt32(0),r.GetInt32(1),r.NullableInt32("OrderID"),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),r.GetDateTime(9),r.NullableDateTime("SentAtUtc"),r.NullableDateTime("ReadAtUtc"),r.GetInt32(12),r.NullableDateTime("DeliveredAtUtc"));private static CustomerNotificationDto Notification(SqlDataReader r)=>new(r.GetInt32(0),r.GetInt32(1),r.NullableInt32("OrderID"),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetBoolean(7),r.GetDateTime(8),r.NullableDateTime("ReadAtUtc"),r.NullableInt32("CustomerMessageID"));private static MessageTemplateDto Template(SqlDataReader r)=>new(r.GetInt32(0),r.GetString(1),r.NullableString("TemplateKey"),r.NullableString("TemplateName"),r.NullableString("Title"),r.NullableString("Channel"),r.NullableString("Body"),r.NullableBoolean("IsActive"),r.NullableDateTime("CreatedAtUtc"),r.NullableDateTime("UpdatedAtUtc"));private async Task<IReadOnlyList<T>> Q<T>(string sql,int? id,Func<SqlDataReader,T> map,CancellationToken ct){await using var c=connections.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand(sql,c);if(id.HasValue)cmd.Parameters.AddWithValue("@id",id.Value);await using var r=await cmd.ExecuteReaderAsync(ct);var x=new List<T>();while(await r.ReadAsync(ct))x.Add(map(r));return x;}}